import { Ui } from "foldkit";

export const { view, legendId, descriptionId } = Ui.Fieldset;

export type FieldsetAttributes<ParentMessage> =
  Ui.Fieldset.FieldsetAttributes<ParentMessage>;
export type ViewConfig<ParentMessage> = Ui.Fieldset.ViewConfig<ParentMessage>;

export {
  descriptionClassName,
  fieldClassName,
  fieldsClassName,
  fieldsetClassName,
  inputClassName,
  labelClassName,
  legendClassName,
  textareaClassName,
} from "./view";

export const fieldsetClassName =
  "rounded-lg border border-gray-200 bg-white p-4 disabled:opacity-60";

export const legendClassName =
  "float-left w-full text-base font-semibold text-gray-950";

export const descriptionClassName = "mt-1 text-sm text-gray-600";

export const fieldsClassName = "mt-4 grid gap-4";

export const fieldClassName = "grid gap-1.5";

export const labelClassName = "text-sm font-medium text-gray-800";

export const inputClassName =
  "h-10 rounded-md border border-gray-300 bg-white px-3 text-sm text-gray-950 outline-none placeholder:text-gray-400 focus:border-accent-500 focus:ring-2 focus:ring-accent-100 disabled:cursor-not-allowed disabled:bg-gray-50 disabled:text-gray-500";

export const textareaClassName =
  "min-h-24 rounded-md border border-gray-300 bg-white px-3 py-2 text-sm text-gray-950 outline-none placeholder:text-gray-400 focus:border-accent-500 focus:ring-2 focus:ring-accent-100 disabled:cursor-not-allowed disabled:bg-gray-50 disabled:text-gray-500";

import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { describe, test } from "vitest";

import * as Fieldset from "./index";

type Model = Readonly<Record<string, never>>;
type Message = never;

const initialModel: Model = {};

const update = (model: Model): readonly [Model, readonly never[]] => [
  model,
  [],
];

const view = (): Html => {
  const h = html<Message>();

  return Fieldset.view<Message>({
    id: "account-fieldset",
    toView: (attributes) =>
      h.fieldset(
        [...attributes.fieldset, h.Class(Fieldset.fieldsetClassName)],
        [
          h.legend(
            [...attributes.legend, h.Class(Fieldset.legendClassName)],
            ["Account"]
          ),
          h.p(
            [...attributes.description, h.Class(Fieldset.descriptionClassName)],
            ["Configure the public account details."]
          ),
          h.div(
            [h.Class(Fieldset.fieldsClassName)],
            [
              h.label(
                [h.Class(Fieldset.fieldClassName)],
                [
                  h.span([h.Class(Fieldset.labelClassName)], ["Display name"]),
                  h.input([
                    h.AriaLabel("Display name"),
                    h.Placeholder("Ada Lovelace"),
                    h.Class(Fieldset.inputClassName),
                  ]),
                ]
              ),
            ]
          ),
        ]
      ),
  });
};

const disabledView = (): Html => {
  const h = html<Message>();

  return Fieldset.view<Message>({
    id: "locked-account-fieldset",
    isDisabled: true,
    toView: (attributes) =>
      h.fieldset(
        [...attributes.fieldset, h.Class(Fieldset.fieldsetClassName)],
        [
          h.legend(
            [...attributes.legend, h.Class(Fieldset.legendClassName)],
            ["Locked account"]
          ),
          h.p(
            [...attributes.description, h.Class(Fieldset.descriptionClassName)],
            ["This group cannot be edited."]
          ),
          h.input([
            h.AriaLabel("Locked display name"),
            h.Disabled(true),
            h.Value("Ada Lovelace"),
            h.Class(Fieldset.inputClassName),
          ]),
        ]
      ),
  });
};

describe("Fieldset registry view", () => {
  test("renders legend, description, and grouped fields", () => {
    Scene.scene(
      { update, view },
      Scene.with(initialModel),
      Scene.expect(Scene.role("group", { name: "Account" })).toExist(),
      Scene.expect(
        Scene.text("Configure the public account details.")
      ).toExist(),
      Scene.expect(Scene.role("textbox", { name: "Display name" })).toExist()
    );
  });

  test("supports disabled fieldset state", () => {
    Scene.scene(
      { update, view: disabledView },
      Scene.with(initialModel),
      Scene.expect(
        Scene.role("group", { name: "Locked account" })
      ).toBeDisabled(),
      Scene.expect(
        Scene.role("textbox", { name: "Locked display name" })
      ).toBeDisabled()
    );
  });
});
